{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "This bill proposes that the department provide funds to each local education agency (LEA) to employ one full-time licensed professional school counselor at every high school with at least 600 students in grades 10 through 12.",
      "rationale": "Conveys the funding obligation, recipient, counselor qualifications, and enrollment threshold. The later appropriation statement supplies the funding condition."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "LEAs may also use the funds to convert a part-time counselor position to a full-time position.",
      "rationale": "Conveys the conversion option but does not specify that the existing part-time position must be at a qualifying high school or expressly convey that conversion satisfies the employment requirement."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "LEAs that already employ one full-time counselor for every 250 student members may use these funds to cover the costs of meeting that ratio.",
      "rationale": "Conveys the existing staffing-ratio condition and permission to offset the costs of counselors needed to meet that ratio."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "LEAs must employ one full-time licensed professional school counselor at every high school for which they receive this funding, unless they already meet the ratio of one counselor per 250 student members.",
      "rationale": "Conveys the funded-school employment requirement and the exception for LEAs already meeting the specified staffing ratio."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "These funds are separate from TISA allocations.",
      "rationale": "In the context of the newly provided funding, conveys that the funds are additional to TISA allocations."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The state board, consulting with the department, may create rules for the roles and responsibilities of these counselors that exceed existing requirements.",
      "rationale": "Conveys discretionary rulemaking, consultation, the funded counselors covered, and authority to impose responsibilities beyond existing requirements."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "The state board must also establish rules for how counselors allocate their time, provided that at least 70% of their time is spent working directly with high school students.",
      "rationale": "Conveys mandatory time-allocation rules and the 70% minimum, but omits the required service categories: preventative and developmental counseling, listed counseling and guidance services, and services supporting additional board-established responsibilities."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "This act is not an appropriation of funds and requires specific appropriation by the general assembly.",
      "rationale": "Conveys that the act itself appropriates nothing and that funding depends on a specific legislative appropriation."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "It would take effect immediately for the purpose of making rules",
      "rationale": "Conveys immediate effectiveness upon enactment for rulemaking purposes."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "and on July 1, 2025, for all other purposes, applying to the 2025-2026 school year and beyond.",
      "rationale": "Conveys the effective date for other purposes and application to the specified school year and subsequent years."
    }
  ]
}
